import { useState } from 'react';
import {
  JxButton,
  JxInputField,
  JxSelect,
  JxStepper,
  JxTextareaField,
} from '@jinx-ui/react';

export interface RegistrationValues {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  comment: string;
}

export interface RegistrationWizardProps {
  onSubmit: (values: RegistrationValues) => void;
}

const emptyValues: RegistrationValues = {
  name: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  comment: '',
};

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const countries = [
  { value: 'ru', label: 'Россия' },
  { value: 'kz', label: 'Казахстан' },
  { value: 'by', label: 'Беларусь' },
  { value: 'am', label: 'Армения' },
];

function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<RegistrationValues>(emptyValues);

  const setField = <K extends keyof RegistrationValues>(
    field: K,
    value: RegistrationValues[K],
  ) => {
    setValues((current) => ({ ...current, [field]: value }));
  };

  const countryLabel =
    countries.find((country) => country.value === values.country)?.label ?? '—';

  const isLastStep = step === steps.length - 1;

  return (
    <div style={{ display: 'grid', gap: '24px' }}>
      <JxStepper steps={steps} current={step} />

      {step === 0 ? (
        <div style={{ display: 'grid', gap: '16px' }}>
          <JxInputField
            label="Имя"
            required
            value={values.name}
            onChange={(event) => setField('name', event.target.value)}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={values.email}
            onChange={(event) => setField('email', event.target.value)}
          />
          <JxInputField
            label="Телефон"
            prefix="+7"
            placeholder="900 000-00-00"
            value={values.phone}
            onChange={(event) => setField('phone', event.target.value)}
          />
        </div>
      ) : null}

      {step === 1 ? (
        <div style={{ display: 'grid', gap: '16px' }}>
          <JxSelect
            label="Страна"
            placeholder="Выберите страну"
            options={countries}
            value={values.country}
            onValueChange={(value) => setField('country', value)}
          />
          <JxInputField
            label="Город"
            required
            value={values.city}
            onChange={(event) => setField('city', event.target.value)}
          />
          <JxInputField
            label="Улица, дом, квартира"
            value={values.street}
            onChange={(event) => setField('street', event.target.value)}
          />
        </div>
      ) : null}

      {step === 2 ? (
        <div style={{ display: 'grid', gap: '16px' }}>
          <dl
            style={{
              display: 'grid',
              gridTemplateColumns: 'minmax(120px, auto) 1fr',
              gap: '8px 16px',
              margin: 0,
              color: 'var(--jx-text-2)',
              fontFamily: 'var(--jx-font-sans)',
            }}
          >
            <dt>Имя</dt>
            <dd style={{ margin: 0, color: 'var(--jx-text)' }}>{values.name || '—'}</dd>
            <dt>Почта</dt>
            <dd style={{ margin: 0, color: 'var(--jx-text)' }}>{values.email || '—'}</dd>
            <dt>Телефон</dt>
            <dd style={{ margin: 0, color: 'var(--jx-text)' }}>{values.phone || '—'}</dd>
            <dt>Страна</dt>
            <dd style={{ margin: 0, color: 'var(--jx-text)' }}>{countryLabel}</dd>
            <dt>Город</dt>
            <dd style={{ margin: 0, color: 'var(--jx-text)' }}>{values.city || '—'}</dd>
            <dt>Адрес</dt>
            <dd style={{ margin: 0, color: 'var(--jx-text)' }}>{values.street || '—'}</dd>
          </dl>
          <JxTextareaField
            label="Комментарий"
            rows={3}
            maxLength={500}
            value={values.comment}
            onChange={(event) => setField('comment', event.target.value)}
            helperText={`${values.comment.length}/500`}
          />
        </div>
      ) : null}

      <div style={{ display: 'flex', gap: '8px', justifyContent: 'flex-end' }}>
        <JxButton
          variant="ghost"
          disabled={step === 0}
          onClick={() => setStep(step - 1)}
        >
          Назад
        </JxButton>
        {isLastStep ? (
          <JxButton variant="primary" onClick={() => onSubmit(values)}>
            Отправить
          </JxButton>
        ) : (
          <JxButton variant="primary" onClick={() => setStep(step + 1)}>
            Дальше
          </JxButton>
        )}
      </div>
    </div>
  );
}

export default RegistrationWizard;

